import random, itertools
from collections import defaultdict
from more_itertools import map_reduce as new_map_reduce

def old_map_reduce(iterable, keyfunc, valuefunc=None, reducefunc=None):
    ret = defaultdict(list)
    if valuefunc is None:
        for item in iterable:
            key = keyfunc(item)
            ret[key].append(item)
    else:
        for item in iterable:
            key = keyfunc(item)
            value = valuefunc(item)
            ret[key].append(value)
    if reducefunc is not None:
        for key, value_list in ret.items():
            ret[key] = reducefunc(value_list)
    ret.default_factory = None
    return ret

class Counting:
    def __init__(self, items):
        self._it = iter(items); self.iter_calls = 0; self.next_calls = 0
    def __iter__(self):
        self.iter_calls += 1; return self
    def __next__(self):
        self.next_calls += 1; return next(self._it)

random.seed(0)
mismatches = 0
trials = 0
for t in range(3000):
    n = random.randrange(0, 12)
    data = [random.randrange(-4, 5) for _ in range(n)]
    mod = random.choice([1, 2, 3, 4])
    use_value = random.random() < 0.5
    use_reduce = random.random() < 0.5
    stop_at = random.choice([None] + list(range(-2, 5)))

    def make_keyfunc(log):
        def keyfunc(x):
            log.append(("key", x))
            if x == stop_at:
                raise ValueError("keyfail")
            return x % mod
        return keyfunc

    def make_valuefunc(log):
        def valuefunc(x):
            log.append(("value", x))
            if x == stop_at:
                raise RuntimeError("valuefail")
            return x * 10 - 3
        return valuefunc

    def make_reducefunc(log):
        def reducefunc(vals):
            log.append(("reduce", tuple(vals)))
            if stop_at == 4 and sum(vals) == 4:
                raise KeyError("reducefail")
            return sum(vals)
        return reducefunc

    logs = {}
    iters = {}
    outs = {}
    errs = {}
    for label, fn in (("old", old_map_reduce), ("new", new_map_reduce)):
        log = []
        it = Counting(data)
        logs[label] = log
        iters[label] = it
        kf = make_keyfunc(log)
        vf = make_valuefunc(log) if use_value else None
        rf = make_reducefunc(log) if use_reduce else None
        try:
            outs[label] = (dict(fn(it, kf, vf, rf)), list(outs.get(label, {}) or []))
        except Exception as e:
            errs[label] = type(e).__name__ + ":" + str(e)
            outs[label] = None
    trials += 1
    ok = (logs["old"] == logs["new"] and iters["old"].iter_calls == iters["new"].iter_calls
          and iters["old"].next_calls == iters["new"].next_calls and errs.get("old") == errs.get("new"))
    # compare results and key order
    old_r, new_r = outs["old"], outs["new"]
    if old_r is not None and new_r is not None:
        ok = ok and old_r == new_r and list(old_r[0]) == list(new_r[0])
    if not ok:
        mismatches += 1
        if mismatches < 4:
            print("MISMATCH", data, mod, use_value, use_reduce, stop_at, logs, iters, outs, errs)
print("trials", trials, "mismatches", mismatches)
'
